int main() {
    int n, k, l;
    cin >> n >> k >> l;
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) {
        long long v;
        cin >> v;
        prefix[i + 1] = prefix[i] + v;
    }
    long long answer = LLONG_MIN;
    for (int i = 0; i + k <= n; i++) {
        long long leftSum = prefix[i + k] - prefix[i];
        for (int j = 0; j + l <= n; j++) {
            int start = max(i, j), end = min(i + k, j + l);
            long long overlap = start < end ? prefix[end] - prefix[start] : 0;
            // the overlap is counted twice in the two sums but must count as -1 times
            answer = max(answer, leftSum + prefix[j + l] - prefix[j] - 3 * overlap);
