import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt(), l = nextInt();
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nextLong();
        long answer = Long.MIN_VALUE;
        for (int i = 0; i + k <= n; i++) {
            long leftSum = prefix[i + k] - prefix[i];
            for (int j = 0; j + l <= n; j++) {
                int start = Math.max(i, j), end = Math.min(i + k, j + l);
                long overlap = start < end ? prefix[end] - prefix[start] : 0;
                // the overlap is counted twice in the two sums but must count as -1 times
                answer = Math.max(answer, leftSum + prefix[j + l] - prefix[j] - 3 * overlap);
            }
        }
        System.out.println(answer);
    }
}

