	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, k, l := next(), next(), next()
	prefix := make([]int, n+1)
	for i := 0; i < n; i++ {
		prefix[i+1] = prefix[i] + next()
	}
	answer := math.MinInt64
	for i := 0; i+k <= n; i++ {
		leftSum := prefix[i+k] - prefix[i]
		for j := 0; j+l <= n; j++ {
			start, end := max(i, j), min(i+k, j+l)
			overlap := 0
			if start < end {
				overlap = prefix[end] - prefix[start]
			}
			// the overlap is counted twice in the two sums but must count as -1 times
			answer = max(answer, leftSum+prefix[j+l]-prefix[j]-3*overlap)
		}
	}
	fmt.Println(answer)
}
